            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      ) : (
          <DesktopLayout 
            gameState={gameState}
            topPlayer={topPlayer}
            bottomPlayer={bottomPlayer}
            activeDecisionPlayerId={activeDecisionPlayerId}
            isInteractive={isInteractive}
            dragState={interactions.dragState}
            handlers={gameHandlers}
            refs={refs}
            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      )}
    </div>
  );
};

import { useState, useRef, useEffect, useCallback } from 'react';
import { GameState, Phase, GameMode, PlayerState, Card, FieldCard, Rank, Color } from '../types';
import { createDeck, createTutorialDeck, sortHand } from '../utils/cards';
import { createFieldCard, getEffectiveColor } from '../utils/rules';
import { generateId, addLog } from '../utils/core';
import { INITIAL_LIFE, MAX_RESOURCES } from '../constants';
import { TUTORIAL_LESSONS } from '../data/tutorials';

interface GameStateRefs {
    handRef: React.RefObject<HTMLDivElement>;
    cpuHandRef: React.RefObject<HTMLDivElement>;
    topDeckRef: React.RefObject<HTMLDivElement>;
    bottomDeckRef: React.RefObject<HTMLDivElement>;
}

interface GameStateProps {
    effects: any; // Using explicit type in real implementation, simplified here for decoupling
    refs: GameStateRefs;
    autoSort: boolean;
}

export const useGameState = ({ effects, refs, autoSort }: GameStateProps) => {
    const [gameState, setGameState] = useState<GameState | null>(null);
    const gameStateRef = useRef<GameState | null>(null);
    const isDrawingInitialRef = useRef(false);

    useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

    const formatCardLog = (card: Card) => `[${card.rank}${card.suit}]`;

    const getActiveDecisionPlayerId = (state: GameState): number => {
        if (state.mode === 'SANDBOX') {
            if (state.isSandboxRun) return state.turnPlayer;
            return state.turnPlayer; 
        }
        if (state.phase === Phase.BLOCK_DECLARE) return state.turnPlayer === 0 ? 1 : 0;
        return state.turnPlayer;
    };

    const startGame = useCallback((mode: GameMode, cpuConfig: { p1: boolean, p2: boolean }, lessonId?: string) => {
        let tutorialConfig = null;
        let initialPhase = mode === 'SANDBOX' ? Phase.MAIN : Phase.INIT_SELECT;

        if (mode === 'TUTORIAL' && lessonId) {
            tutorialConfig = TUTORIAL_LESSONS.find(l => l.id === lessonId);
            if (tutorialConfig && tutorialConfig.setup) {
                initialPhase = tutorialConfig.setup.phase;
            }
        }

        let sharedDeck: Card[] = [];
        if (mode === 'STREET') sharedDeck = createDeck();
        else if (mode === 'TUTORIAL' && !tutorialConfig?.setup) sharedDeck = createTutorialDeck();

        const createPlayer = (id: number, name: string, isCpu: boolean): PlayerState => {
            let hand: Card[] = [];
            let resources: FieldCard[] = [];
            let field: FieldCard[] = [];
            let life = INITIAL_LIFE;

            if (mode === 'TUTORIAL' && tutorialConfig?.setup) {
                if (id === 0) {
                    hand = tutorialConfig.setup.p1Hand || [];
                    resources = (tutorialConfig.setup.p1Resources || []).map(c => createFieldCard(c, 0));
                    if (tutorialConfig.setup.p1Field) {
                        field = tutorialConfig.setup.p1Field.map(c => {
                            const fc = createFieldCard(c, 0);
                            fc.instanceId = c.id; 
                            fc.isSummoningSick = false;
                            return fc;
                        });
                    }
                    if (tutorialConfig.setup.p1Life) life = tutorialConfig.setup.p1Life;
                } else {
                    hand = tutorialConfig.setup.p2Hand || [];
                    if (tutorialConfig.setup.p2Field) {
                        field = tutorialConfig.setup.p2Field.map(c => {
                            const fc = createFieldCard(c, 1);
                            fc.instanceId = c.id; 
                            fc.isSummoningSick = false;
                            return fc;
                        });
                    }
                    if (tutorialConfig.setup.p2Life) life = tutorialConfig.setup.p2Life;
                }
            }

            return {
                id, name, isCpu, life, hand, 
                library: mode === 'PRO' ? createDeck() : [],
                resources, field, discard: [],
                consecutiveDrawFailures: 0,
                hasAttackedThisTurn: false
            };
        };

        const p1 = createPlayer(0, cpuConfig.p1 ? "CPU 1" : "Player 1", cpuConfig.p1);
        const p2 = createPlayer(1, cpuConfig.p2 ? "CPU 2" : "Player 2", cpuConfig.p2);

        const initialState: GameState = {
            mode,
            deck: sharedDeck,
            players: [p1, p2],
            turnPlayer: 0, 
            startingPlayerId: 0, 
            phase: initialPhase,
            turnCount: 1,
            pendingAttackers: [],
            pendingBlocks: {},
            selectedCardId: null,
            activeCombatCardId: null,
            initSelectedIds: [],
            targetMode: 'NONE',
            sourceCardId: null,
            winner: null,
            recentDamage: {},
            logs: [{ id: generateId(), text: `Game Started. Mode: ${mode}.` }],
            tutorialState: mode === 'TUTORIAL' && tutorialConfig ? {
                active: true,
                lessonId,
                currentStepIndex: 0,
                steps: tutorialConfig.steps
            } : undefined
        };
        setGameState(initialState);
    }, []);

    const checkGameOver = (state: GameState) => {
        if (state.players[0].life <= 0) state.winner = 1;
        else if (state.players[1].life <= 0) state.winner = 0;
        if (state.winner !== null) state.phase = Phase.GAME_OVER;
    };

    const drawCards = async (playerId: number, count: number) => {
        const startState = gameStateRef.current;
        if (!startState) return;
        const pIndex = startState.players.findIndex(p => p.id === playerId);
        const isSpectate = startState.players[0].isCpu && startState.players[1].isCpu;
        const isHotseat = !startState.players[1].isCpu || startState.players[0].isCpu;
        const viewId = (isHotseat && !isSpectate) ? startState.turnPlayer : 0;
        const isBottom = playerId === viewId;

        const deck = startState.mode === 'STREET' || startState.mode === 'TUTORIAL' ? startState.deck : startState.players[pIndex].library;
        const cardsToDraw = deck.slice(0, Math.min(count, deck.length));
        const failuresNeeded = count - cardsToDraw.length;

        for (const card of cardsToDraw) {
             let startRect = isBottom ? refs.bottomDeckRef.current?.getBoundingClientRect() : refs.topDeckRef.current?.getBoundingClientRect();
             let targetRect = isBottom ? refs.handRef.current?.getBoundingClientRect() : refs.cpuHandRef.current?.getBoundingClientRect();

             if (isSpectate && playerId === 1) {
                 startRect = refs.topDeckRef.current?.getBoundingClientRect();
                 targetRect = refs.cpuHandRef.current?.getBoundingClientRect();
             }

             if (startRect && targetRect) { effects.triggerFlyer(card, startRect, targetRect); }

             setGameState(prev => {
                 if (!prev) return null;
                 const nextPlayers = [...prev.players];
                 const nextP = { ...nextPlayers[pIndex] };
                 let nextDeck = prev.deck;
                 if (prev.mode === 'STREET' || prev.mode === 'TUTORIAL') { nextDeck = prev.deck.filter(c => c.id !== card.id); } 
                 else { nextP.library = nextP.library.filter(c => c.id !== card.id); }
                 nextP.hand = [...nextP.hand, card];
                 if (autoSort) nextP.hand = sortHand(nextP.hand);
                 nextPlayers[pIndex] = nextP;
                 return { ...prev, deck: prev.mode === 'STREET' || prev.mode === 'TUTORIAL' ? nextDeck : prev.deck, players: nextPlayers };
             });
             await new Promise(r => setTimeout(r, 60));
        }
        if (cardsToDraw.length > 0) { setGameState(prev => prev ? { ...prev, logs: addLog(prev, `${startState.players[pIndex].name} drew ${cardsToDraw.length} cards.`) } : null); }
        if (failuresNeeded > 0) {
            setGameState(prev => {
                 if (!prev) return null;
                 const nextPlayers = prev.players.map(pl => pl.id === playerId ? { ...pl, consecutiveDrawFailures: pl.consecutiveDrawFailures + failuresNeeded } : pl);
                 return { ...prev, players: nextPlayers, logs: addLog(prev, "Deck Empty!") };
            });
            setTimeout(() => { if (gameStateRef.current) checkGameOver(gameStateRef.current); }, 100);
        }
    };

    const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
        setGameState(prev => {
            if (!prev && !overrideState) return null;
            let newState = overrideState ? { ...overrideState } : { ...prev! };
            newState.phase = targetPhase;
            const player = newState.players[newState.turnPlayer];

            switch (targetPhase) {
                case Phase.UPKEEP:
                    newState.players.forEach(p => {
                        if (p.id === newState.turnPlayer) {
                            p.field.forEach(c => { c.isTapped = false; c.isSummoningSick = false; });
                            p.resources.forEach(r => r.isTapped = false);
                        }
                    });
                    newState.pendingAttackers = []; newState.pendingBlocks = {}; newState.selectedCardId = null; newState.recentDamage = {}; newState.activeCombatCardId = null;
                    player.hasAttackedThisTurn = false;
                    newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
                    setTimeout(() => advancePhase(Phase.DRAW), 800);
                    break;
                case Phase.DRAW:
                    if (newState.mode === 'TUTORIAL') {
                        setTimeout(() => advancePhase(Phase.MAIN), 400);
                        return { ...newState, phase: Phase.RESOURCE_START };
                    }
                    setTimeout(() => {
                        drawCards(player.id, 1).then(() => {
                            setGameState(current => {
                                if(!current) return null;
                                const p = current.players[current.turnPlayer];
                                const isTurn1FirstPlayer = current.turnCount === 1 && current.turnPlayer === current.startingPlayerId;
                                const hasMaxResources = p.resources.length >= MAX_RESOURCES;
                                if (isTurn1FirstPlayer || hasMaxResources) {
                                    setTimeout(() => advancePhase(Phase.MAIN), 400);
                                    return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, isTurn1FirstPlayer ? "Turn 1: Resource Step skipped." : "Max Resources reached.") };
                                } else { return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") }; }
                            });
                        });
                    }, 0);
                    break;
                case Phase.RESOURCE_START: break;
                case Phase.MAIN: newState.logs = addLog(newState, "Main Phase."); break;
                case Phase.ATTACK_DECLARE: newState.logs = addLog(newState, "Declare Attackers."); break;
                case Phase.BLOCK_DECLARE:
                    const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
                    newState.logs = addLog(newState, `${defender.name} declares blocks.`);
                    break;
            }
            return newState;
        });
    };

    const playCard = async (card: Card, targetId?: string, targetOwnerId?: number) => {
        let cardIdx = -1; let playedCard: Card | null = null;
        const isFaceCard = ['K', 'Q', 'J'].includes(card.rank);
        const currentState = gameStateRef.current;
        if (!currentState) return;

        if (card.rank === 'K' || card.rank === 'Q') {
            if (!targetId || targetOwnerId === undefined) return;
            const targetP = currentState.players.find(p => p.id === targetOwnerId);
            const targetF = targetP?.field.find(f => f.instanceId === targetId);
            if (!targetF) return; 
            if (card.rank === 'K' && getEffectiveColor(targetF) !== card.baseColor) { 
                setGameState(prev => prev ? ({ ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") }) : null);
                return; 
            }
        }

        if (isFaceCard) {
            let targetRect: DOMRect | undefined;
            if (targetId) { const targetEl = document.getElementById(targetId); if (targetEl) targetRect = targetEl.getBoundingClientRect(); }
            effects.setSpecialAnim({ type: card.rank as 'K'|'Q'|'J', card, targetRect });
            await new Promise(r => setTimeout(r, card.rank === 'K' ? 1200 : card.rank === 'Q' ? 1000 : 800));
            effects.setSpecialAnim(null);
        } else {
            const cardEl = document.getElementById(card.id);
            const fieldEl = document.getElementById('field-area');
            if (cardEl && fieldEl) {
                await effects.triggerFlyer(card, cardEl.getBoundingClientRect(), fieldEl.getBoundingClientRect());
            }
        }

        setGameState(prev => {
            if (!prev) return null;
            const p = prev.players[prev.turnPlayer];
            cardIdx = p.hand.findIndex(c => c.id === card.id);
            if (cardIdx === -1) return prev;
            const newHand = [...p.hand];
            [playedCard] = newHand.splice(cardIdx, 1);
            let toTap = card.cost;
            const newResources = p.resources.map(r => {
                if (!r.isTapped && toTap > 0) { toTap--; return { ...r, isTapped: true }; }
                return r;
            });
            const nextState = { ...prev, players: [...prev.players] };
            const nextPlayer = { ...p, hand: newHand, resources: newResources };
            nextState.players[prev.turnPlayer] = nextPlayer;

            if (card.rank === 'J') { 
                nextPlayer.discard.push(playedCard!); 
                return { ...nextState, logs: addLog(nextState, `Played Jack ${formatCardLog(card)}.`) }; 
            } else if (card.rank === 'K') {
                const targetP = nextState.players[targetOwnerId!];
                const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
                if (targetFIdx === -1) return prev; 
                const targetF = targetP.field[targetFIdx];
                if (getEffectiveColor(targetF) !== card.baseColor) return prev;
                effects.triggerExplosion(targetId!); 
                nextPlayer.discard.push(playedCard!); 
                targetP.field.splice(targetFIdx, 1); 
                targetP.discard.push(targetF.card, ...targetF.attachedCards);
                return { ...nextState, logs: addLog(nextState, `King ${formatCardLog(card)} executed ${formatCardLog(targetF.card)}.`) };
            } else if (card.rank === 'Q') {
                const targetP = nextState.players[targetOwnerId!];
                const targetF = targetP.field.find(f => f.instanceId === targetId);
                if(targetF) {
                    const existingQueens = targetF.attachedCards.filter(c => c.rank === Rank.Queen);
                    if (existingQueens.length > 0) { targetP.discard.push(...existingQueens); targetF.attachedCards = targetF.attachedCards.filter(c => c.rank !== Rank.Queen); }
                    targetF.attachedCards.push(playedCard!);
                }
                return { ...nextState, logs: addLog(nextState, `Queen ${formatCardLog(card)} shifted ${targetF ? formatCardLog(targetF.card) : 'target'}.`) };
            } else {
                const newSoldier = createFieldCard(playedCard!, p.id); 
                if (prev.mode === 'TUTORIAL') {
                    newSoldier.instanceId = card.id;
                }
                nextPlayer.field.push(newSoldier);
                return { ...nextState, logs: addLog(nextState, `Conscripted ${formatCardLog(card)}.`) };
            }
        });

        if (card.rank === 'J' && gameStateRef.current) { await drawCards(gameStateRef.current.turnPlayer, 2); }
    };

    const performEndTurn = () => {
        setGameState(prev => {
            if(!prev) return null;
            if (prev.mode === 'TUTORIAL' && prev.tutorialState?.lessonId === 'lesson-2') {
                if (prev.turnPlayer === 0) {
                    const nextPlayers = [...prev.players];
                    const p2 = { ...nextPlayers[1] };
                    p2.field = p2.field.map(f => {
                        if (f.instanceId === 'tut-5-♥') return { ...f, isTapped: true };
                        return f;
                    });
                    nextPlayers[1] = p2;
                    const nextState = { ...prev, players: nextPlayers, turnPlayer: 1, phase: Phase.BLOCK_DECLARE }; 
                    nextState.pendingAttackers = ['tut-5-♥'];
                    nextState.logs = addLog(nextState, "CPU 2 attacks with [5♥].");
                    return nextState;
                } else if (prev.turnPlayer === 1) {
                    const nextPlayers = prev.players.map(p => ({
                        ...p,
                        hasAttackedThisTurn: false,
                        field: p.id === 0 ? p.field.map(f => ({...f, isTapped: false, isSummoningSick: false})) : p.field,
                        resources: p.id === 0 ? p.resources.map(r => ({...r, isTapped: false})) : p.resources
                    }));
                    const nextState = { ...prev, players: nextPlayers, turnPlayer: 0, turnCount: prev.turnCount + 1, phase: Phase.MAIN, logs: addLog(prev, "Your Turn.") };
                    return nextState;
                }
            }
            const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
            const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;
            const nextState = { ...prev, turnPlayer: nextPlayerIdx, turnCount: nextTurnCount, phase: Phase.UPKEEP };
            setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
            return nextState; 
        });
        effects.setShowTurnAnim(true);
    };

    const confirmAttack = () => {
        setGameState(prev => {
            if(!prev) return null;
            if (prev.mode === 'TUTORIAL' && prev.tutorialState?.lessonId === 'lesson-2' && prev.turnPlayer === 0 && prev.phase === Phase.ATTACK_DECLARE) {
                if (prev.turnCount > 1) {
                    const p = prev.players[0];
                    const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
                    const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
                    p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
                    p.hasAttackedThisTurn = true;
                    return { ...prev, phase: Phase.DAMAGE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}. Direct Hit!`) };
                }
                const blocks: Record<string, string> = {};
                blocks['tut-2-♠'] = 'tut-2-♣';
                const p = prev.players[0];
                const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
                const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
                p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
                p.hasAttackedThisTurn = true;
                return { ...prev, pendingBlocks: blocks, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}.`) };
            }
            if (prev.pendingAttackers.length === 0) return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
            const p = prev.players[prev.turnPlayer];
            const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
            const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
            p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
            p.hasAttackedThisTurn = true;
            const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
            const attackingColors = new Set(attackers.map(getEffectiveColor));
            const untappedDefenders = defender.field.filter(f => !f.isTapped);
            const canDefend = untappedDefenders.some(def => attackingColors.has(getEffectiveColor(def)));
            if (!canDefend) return { ...prev, phase: Phase.DAMAGE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}. Direct Hit!`) };
            return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}.`) };
        });
    };

    const confirmBlocks = () => { setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null); };

    // Resolve Combat Loop
    useEffect(() => { 
        if (gameState?.phase === Phase.DAMAGE) {
            (async () => {
                const state = gameStateRef.current!;
                const attackerPlayer = state.players[state.turnPlayer];
                const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
                const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));
                const directAttackers = attackers.filter(atk => !Object.values(state.pendingBlocks).includes(atk.instanceId));

                // Blocked Combats
                for (const atk of attackers) {
                    const blockerId = Object.keys(state.pendingBlocks).find(k => state.pendingBlocks[k] === atk.instanceId);
                    if (blockerId) {
                        setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
                        await new Promise(r => setTimeout(r, 400));
                        setGameState(prev => {
                            if (!prev) return null;
                            const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                            if (!blk) return prev;
                            const nextRecentDamage = { ...prev.recentDamage };
                            nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                            nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                            const logMsg = `⚔️ Battle: ${formatCardLog(atk.card)} (${atk.card.numericValue}) vs ${formatCardLog(blk.card)} (${blk.card.numericValue})`;
                            return { ...prev, recentDamage: nextRecentDamage, logs: addLog(prev, logMsg) };
                        });
                        await new Promise(r => setTimeout(r, 600)); 
                        setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
                        await new Promise(r => setTimeout(r, 100));
                    }
                }

                // Direct Attacks
                for (const atk of directAttackers) {
                    setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
                    await new Promise(r => setTimeout(r, 100));
                    const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;

                    const applyDamage = () => {
                        setGameState(prev => {
                            if (!prev) return null;
                            const nextPlayers = [...prev.players];
                            const defIdx = nextPlayers.findIndex(p => p.id === defenderPlayer.id);
                            if (defIdx > -1) { 
                                nextPlayers[defIdx] = { ...nextPlayers[defIdx], life: Math.max(0, nextPlayers[defIdx].life - dmg) }; 
                            }
                            let nextState = { ...prev, players: nextPlayers };
                            if (nextPlayers[defIdx].life <= 0 && nextState.winner === null) {
                                nextState.winner = attackerPlayer.id;
                                nextState.phase = Phase.GAME_OVER;
                            }
                            return nextState;
                        });
                    };
                    effects.addDamageAnim(dmg, defenderPlayer.id, applyDamage);

                    setGameState(prev => prev ? { ...prev, logs: addLog(prev, `🔥 Direct Hit! ${formatCardLog(atk.card)} deals ${dmg} damage.`) } : null);
                    await new Promise(r => setTimeout(r, 300));
                    setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
                }

                // Cleanup
                setGameState(prev => {
                    if (!prev) return null;
                    const nextState = { ...prev };
                    const atkP = nextState.players[nextState.turnPlayer];
                    const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];
                    const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

                    activeAtk.forEach(atk => {
                        const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);
                        if (blockerId) {
                            const blk = defP.field.find(f => f.instanceId === blockerId);
                            if (blk) {
                                const atkVal = atk.card.numericValue; const blkVal = blk.card.numericValue;
                                const atkIsAce = atk.card.rank === 'A'; const blkIsAce = blk.card.rank === 'A';
                                let atkDies = false; let blkDies = false;
                                if (atkIsAce) blkDies = true; if (blkIsAce) atkDies = true;
                                if (!atkIsAce && !blkIsAce) {
                                    if (atkVal > blkVal) blkDies = true; else if (blkVal > atkVal) atkDies = true; else { atkDies = true; blkDies = true; }
                                } else { if(atkIsAce && !blkIsAce) atkDies = true; if(blkIsAce && !atkIsAce) blkDies = true; }

                                if (atkDies) { effects.triggerExplosion(atk.instanceId); atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId); atkP.discard.push(atk.card, ...atk.attachedCards); }
                                if (blkDies) { effects.triggerExplosion(blk.instanceId); defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId); defP.discard.push(blk.card, ...blk.attachedCards); }
                            }
                        } 
                    });
                    nextState.recentDamage = {}; nextState.pendingAttackers = []; nextState.pendingBlocks = {}; nextState.phase = Phase.MAIN;

                    if (defP.life <= 0) nextState.winner = atkP.id;
                    if (atkP.life <= 0) nextState.winner = defP.id;
                    if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;
                    return nextState;
                });
            })();
        }
    }, [gameState?.phase]);

    return {
        gameState, setGameState, gameStateRef,
        startGame,
        drawCards,
        playCard,
        advancePhase,
        performEndTurn,
        confirmAttack,
        confirmBlocks,
        isDrawingInitialRef,
        getActiveDecisionPlayerId
    };
};

import { useState } from 'react';
import { Card, Phase, DragState } from '../types';
import { createFieldCard, canBlock, getEffectiveColor } from '../utils/rules';
import { addLog } from '../utils/core';
import { sortHand } from '../utils/cards';

export const useGameInteractions = (
    gameState: any, 
    actions: any, 
    effects: any, 
    tutorial: any, 
    ui: any,
    refs: any
) => {
    const [dragState, setDragState] = useState<DragState | null>(null);

    const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string, fromCpu: boolean = false) => {
        const currentState = actions.gameStateRef.current;
        if (!currentState) return;

        const elementId = instanceId || card.id;
        if (currentState.mode === 'TUTORIAL') {
            if (!tutorial.isInteractionAllowed(elementId)) {
                console.log("Tutorial Blocked Interaction:", elementId);
                return;
            }
        }

        if (currentState.mode === 'SANDBOX' && !currentState.isSandboxRun) { 
            ui.setCardActionTarget({ card, loc: location, ownerId, instanceId }); 
            return; 
        }

        const activePlayerId = actions.getActiveDecisionPlayerId(currentState);
        if (!fromCpu && currentState.players[activePlayerId].isCpu && ownerId === activePlayerId) { if (currentState.phase !== Phase.INIT_SELECT) return; }

        if (currentState.phase === Phase.INIT_SELECT && location === 'HAND') {
            if (ownerId === activePlayerId) {
                actions.setGameState((prev: any) => {
                    if(!prev) return null;
                    const isSelected = prev.initSelectedIds.includes(card.id);
                    let newIds = isSelected ? prev.initSelectedIds.filter((id: string) => id !== card.id) : [...prev.initSelectedIds, card.id];
                    if (newIds.length > 3) newIds.pop();
                    return { ...prev, initSelectedIds: newIds };
                });
                if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
            }
        }
        else if (currentState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
            const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
            let cardEl = document.getElementById(card.id); 
            if (cardEl && targetResourceContainer) { await effects.triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect()); }
            actions.setGameState((prev: any) => {
               if(!prev) return null;
               const p = prev.players[activePlayerId];
               const cardIdx = p.hand.findIndex((c: any) => c.id === card.id);
               const [resCard] = p.hand.splice(cardIdx, 1);
               p.resources.push(createFieldCard(resCard, p.id));
               return { ...prev, phase: Phase.MAIN, logs: addLog(prev, `Converted [${resCard.rank}${resCard.suit}] into a resource.`) };
            });
            await actions.drawCards(activePlayerId, 1);
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
             actions.setGameState((prev: any) => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
            if (currentState.selectedCardId) {
                const handCardEl = document.getElementById(currentState.selectedCardId);
                const resCardEl = instanceId ? document.getElementById(instanceId) : null; 
                const handContainer = refs.handRef.current;
                const handCard = currentState.players[activePlayerId].hand.find((c: any) => c.id === currentState.selectedCardId);
                if (handCard && handCardEl && resCardEl && handContainer) {
                    const p1 = effects.triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                    const p2 = effects.triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                    await Promise.all([p1, p2]);
                }
            }
            actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const handIdx = p.hand.findIndex((c: any) => c.id === prev.selectedCardId);
                const resIdx = p.resources.findIndex((c: any) => c.card.id === card.id);
                if(handIdx > -1 && resIdx > -1) {
                    const handCard = p.hand[handIdx]; const resFieldCard = p.resources[resIdx];
                    p.hand[handIdx] = resFieldCard.card; p.resources[resIdx] = createFieldCard(handCard, p.id); 
                    if(ui.autoSort) p.hand = sortHand(p.hand);
                    return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, `Swapped resource.`) };
                }
                return { ...prev, selectedCardId: null, phase: Phase.MAIN };
            });
        }
        else if (currentState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
             actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const fieldCard = p.field.find((fc: any) => fc.instanceId === instanceId);
                if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
                const isAttacking = prev.pendingAttackers.includes(instanceId!);
                const newPending = isAttacking ? prev.pendingAttackers.filter((id: string) => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
                return { ...prev, pendingAttackers: newPending as string[] };
            });
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
            if (instanceId && currentState.pendingBlocks[instanceId]) { 
                actions.setGameState((prev: any) => {
                  if(!prev) return null;
                  const newBlocks = { ...prev.pendingBlocks };
                  delete newBlocks[instanceId];
                  return { ...prev, pendingBlocks: newBlocks };
                });
            }
        }
        else if (currentState.phase === Phase.MAIN && location === 'HAND' && ownerId === activePlayerId) {
             const player = currentState.players[activePlayerId];
             const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;

             if (untappedRes < card.cost) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
                 return;
             }

             if (['K', 'Q'].includes(card.rank)) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Drag Face Cards to target!") }));
             } else {
                 actions.playCard(card);
                 if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('PLAY_CARD', card.id);
             }
        }
    };

    const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
        if (!gameState) return;
        if (gameState.mode === 'TUTORIAL') {
            const id = instanceId || card.id;
            if (!tutorial.isInteractionAllowed(id)) return;
        }

        if (gameState.mode === 'SANDBOX' && !gameState.isSandboxRun) {
             setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
             return;
        }
        const activePid = actions.getActiveDecisionPlayerId(gameState);
        if (ownerId !== activePid) return;

        if (gameState.players[activePid].isCpu) return;

        if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
        else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
        else { return; }
        setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
        e.stopPropagation();
    };

    const handleDrop = (e: MouseEvent) => {
        if (!dragState || !gameState) return;
        const elements = document.elementsFromPoint(e.clientX, e.clientY);
        const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');
        if (!targetElement) {
             setDragState(null);
             return;
        }

        if (dragState.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetElement.id === 'field-area' || targetInstanceId) { 
                const player = gameState.players[gameState.turnPlayer];
                const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;
                if (untappedRes < dragState.cardObj.cost) { 
                    actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") })); 
                } else {
                    if (dragState.cardObj.rank === 'Q' || dragState.cardObj.rank === 'K') {
                        if (targetInstanceId) {
                            let targetOwnerId = -1;
                            gameState.players.forEach((p: any) => { if (p.field.some((f: any) => f.instanceId === targetInstanceId)) targetOwnerId = p.id; });
                            if (targetOwnerId !== -1) actions.playCard(dragState.cardObj, targetInstanceId, targetOwnerId);
                        }
                    } else { 
                        actions.playCard(dragState.cardObj); 
                    }
                    if (gameState.mode === 'TUTORIAL') {
                         tutorial.advanceTutorialStep('PLAY_CARD', dragState.cardObj.id);
                    }
                }
            }
        }
        else if (dragState.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetInstanceId && dragState.instanceId) { 
                 const blockerInstanceId = dragState.instanceId;
                 const attackerInstanceId = targetInstanceId;

                 actions.setGameState((prev: any) => {
                    if (!prev) return null;
                    if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;
                    const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
                    const blocker = defP.field.find((f: any) => f.instanceId === blockerInstanceId);
                    const attacker = prev.players[prev.turnPlayer].field.find((f: any) => f.instanceId === attackerInstanceId);
                    if (!blocker || !attacker || blocker.isTapped) return prev;
                    if (!canBlock(attacker, blocker)) return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
                    const newBlocks = { ...prev.pendingBlocks };
                    newBlocks[blockerInstanceId] = attackerInstanceId;
                    return { ...prev, pendingBlocks: newBlocks };
                });

                if (gameState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('DECLARE_BLOCK', blockerInstanceId);
            }
        }
        setDragState(null);
    };

    const handleConfirmInitSelection = async () => {
         const activeId = actions.getActiveDecisionPlayerId(gameState!);
         if (gameState?.mode === 'TUTORIAL') {
             if (!tutorial.isInteractionAllowed('btn-confirm-init')) return;
             tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-init');
         }

         const p = gameState!.players[activeId];
         const selectedCards = p.hand.filter((c: any) => gameState!.initSelectedIds.includes(c.id));
         const resContainer = document.getElementById(`resource-container-${activeId}`);

         if (resContainer) {
             const resRect = resContainer.getBoundingClientRect();
             const animations = selectedCards.map((c: any) => {
                 const el = document.getElementById(c.id);
                 if (el) return effects.triggerFlyer(c, el.getBoundingClientRect(), resRect);
                 return Promise.resolve();
             });
             await Promise.all(animations);
         }

         actions.setGameState((prev: any) => {
            if (!prev) return null;
            const p = prev.players[activeId];
            const selected = p.hand.filter((c: any) => prev.initSelectedIds.includes(c.id));
            const remaining = p.hand.filter((c: any) => !prev.initSelectedIds.includes(c.id));
            p.hand = remaining;
            selected.forEach((c: any) => p.resources.push(createFieldCard(c, p.id)));
            const otherId = activeId === 0 ? 1 : 0;
            const other = prev.players[otherId];
            let nextState = { ...prev, initSelectedIds: [] };
            let gameStarting = false;

            if (other.isCpu) {
                // Should invoke AI selection here, but for simplicity let AI hook handle it or do it here. 
                // Wait, if AI hook handles it, we leave this alone. 
                // But the logic in original App.tsx was handled here for instant transition.
                // Re-implement basic CPU finish to prevent hanging if useGameAI hasn't picked up yet?
                // Actually, useGameAI handles INIT_SELECT.
                // We just switch turn.
                nextState.turnPlayer = otherId;
                // But wait, if P2 is CPU, we want to transition to Game Start immediately?
                // Original code did logic here. Let's keep it simple: Just switch turn. 
                // The AI hook will see INIT_SELECT and act.
            } else {
                if (other.resources.length === 3) {
                    nextState.logs = addLog(nextState, "Battle Commencing!");
                    nextState.phase = Phase.UPKEEP; nextState.turnPlayer = prev.startingPlayerId;
                    gameStarting = true;
                    setTimeout(() => actions.advancePhase(Phase.UPKEEP, nextState), 500);
                } else { 
                    nextState.turnPlayer = otherId; 
                    nextState.logs = addLog(nextState, `${other.name}'s turn to setup.`); 
                }
            }
            if (gameStarting) setTimeout(() => effects.setShowTurnAnim(true), 100);
            return nextState;
         });
    };

    const handlePhaseAction = (action: 'ATTACK_PHASE' | 'END_TURN' | 'CONFIRM_ATTACK' | 'CONFIRM_BLOCK' | 'ADD_RESOURCE' | 'SWAP_RESOURCE' | 'CANCEL_RESOURCE' | 'CONFIRM_INIT') => {
        if(action === 'ATTACK_PHASE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-attack-phase')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-attack-phase');
             }
             actions.advancePhase(Phase.ATTACK_DECLARE);
        }
        else if (action === 'END_TURN') {
             if (!tutorial.isInteractionAllowed('btn-end-turn')) return;
             ui.setShowEndTurnModal(true);
        }
        else if (action === 'CONFIRM_ATTACK') actions.confirmAttack();
        else if (action === 'CONFIRM_BLOCK') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-confirm-blocks') && !tutorial.isInteractionAllowed('btn-tutorial-next')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-blocks');
             }
             actions.confirmBlocks();
        }
        else if (action === 'ADD_RESOURCE') actions.advancePhase(Phase.RESOURCE_ADD_SELECT);
        else if (action === 'SWAP_RESOURCE') actions.advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
        else if (action === 'CANCEL_RESOURCE') actions.setGameState((prev: any) => prev ? { ...prev, phase: Phase.RESOURCE_START, selectedCardId: null } : null);
        else if (action === 'CONFIRM_INIT') handleConfirmInitSelection();
    };

    return {
        dragState, setDragState,
        handleCardClick,
        handleDragStart,
        handleDrop,
        handlePhaseAction,
        handleConfirmInitSelection // Exported for AI use
    };
};

import { useState } from 'react';
import { Card, Phase, DragState } from '../types';
import { createFieldCard, canBlock, getEffectiveColor } from '../utils/rules';
import { addLog } from '../utils/core';
import { sortHand } from '../utils/cards';

export const useGameInteractions = (
    gameState: any, 
    actions: any, 
    effects: any, 
    tutorial: any, 
    ui: any,
    refs: any
) => {
    const [dragState, setDragState] = useState<DragState | null>(null);

    const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string, fromCpu: boolean = false) => {
        const currentState = actions.gameStateRef.current;
        if (!currentState) return;

        const elementId = instanceId || card.id;
        if (currentState.mode === 'TUTORIAL') {
            if (!tutorial.isInteractionAllowed(elementId)) {
                console.log("Tutorial Blocked Interaction:", elementId);
                return;
            }
        }

        if (currentState.mode === 'SANDBOX' && !currentState.isSandboxRun) { 
            ui.setCardActionTarget({ card, loc: location, ownerId, instanceId }); 
            return; 
        }

        const activePlayerId = actions.getActiveDecisionPlayerId(currentState);
        if (!fromCpu && currentState.players[activePlayerId].isCpu && ownerId === activePlayerId) { if (currentState.phase !== Phase.INIT_SELECT) return; }

        if (currentState.phase === Phase.INIT_SELECT && location === 'HAND') {
            if (ownerId === activePlayerId) {
                actions.setGameState((prev: any) => {
                    if(!prev) return null;
                    const isSelected = prev.initSelectedIds.includes(card.id);
                    let newIds = isSelected ? prev.initSelectedIds.filter((id: string) => id !== card.id) : [...prev.initSelectedIds, card.id];
                    if (newIds.length > 3) newIds.pop();
                    return { ...prev, initSelectedIds: newIds };
                });
                if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
            }
        }
        else if (currentState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
            const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
            let cardEl = document.getElementById(card.id); 
            if (cardEl && targetResourceContainer) { await effects.triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect()); }
            actions.setGameState((prev: any) => {
               if(!prev) return null;
               const p = prev.players[activePlayerId];
               const cardIdx = p.hand.findIndex((c: any) => c.id === card.id);
               const [resCard] = p.hand.splice(cardIdx, 1);
               p.resources.push(createFieldCard(resCard, p.id));
               return { ...prev, phase: Phase.MAIN, logs: addLog(prev, `Converted [${resCard.rank}${resCard.suit}] into a resource.`) };
            });
            await actions.drawCards(activePlayerId, 1);
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
             actions.setGameState((prev: any) => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
        }
        else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
            if (currentState.selectedCardId) {
                const handCardEl = document.getElementById(currentState.selectedCardId);
                const resCardEl = instanceId ? document.getElementById(instanceId) : null; 
                const handContainer = refs.handRef.current;
                const handCard = currentState.players[activePlayerId].hand.find((c: any) => c.id === currentState.selectedCardId);
                if (handCard && handCardEl && resCardEl && handContainer) {
                    const p1 = effects.triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                    const p2 = effects.triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                    await Promise.all([p1, p2]);
                }
            }
            actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const handIdx = p.hand.findIndex((c: any) => c.id === prev.selectedCardId);
                const resIdx = p.resources.findIndex((c: any) => c.card.id === card.id);
                if(handIdx > -1 && resIdx > -1) {
                    const handCard = p.hand[handIdx]; const resFieldCard = p.resources[resIdx];
                    p.hand[handIdx] = resFieldCard.card; p.resources[resIdx] = createFieldCard(handCard, p.id); 
                    if(ui.autoSort) p.hand = sortHand(p.hand);
                    return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, `Swapped resource.`) };
                }
                return { ...prev, selectedCardId: null, phase: Phase.MAIN };
            });
        }
        else if (currentState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
             actions.setGameState((prev: any) => {
                if(!prev) return null;
                const p = prev.players[activePlayerId];
                const fieldCard = p.field.find((fc: any) => fc.instanceId === instanceId);
                if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
                const isAttacking = prev.pendingAttackers.includes(instanceId!);
                const newPending = isAttacking ? prev.pendingAttackers.filter((id: string) => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
                return { ...prev, pendingAttackers: newPending as string[] };
            });
            if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('CLICK_CARD', card.id);
        }
        else if (currentState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
            if (instanceId && currentState.pendingBlocks[instanceId]) { 
                actions.setGameState((prev: any) => {
                  if(!prev) return null;
                  const newBlocks = { ...prev.pendingBlocks };
                  delete newBlocks[instanceId];
                  return { ...prev, pendingBlocks: newBlocks };
                });
            }
        }
        else if (currentState.phase === Phase.MAIN && location === 'HAND' && ownerId === activePlayerId) {
             const player = currentState.players[activePlayerId];
             const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;

             if (untappedRes < card.cost) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
                 return;
             }

             if (['K', 'Q'].includes(card.rank)) {
                 actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Drag Face Cards to target!") }));
             } else {
                 actions.playCard(card);
                 if (currentState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('PLAY_CARD', card.id);
             }
        }
    };

    const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
        if (!gameState) return;
        if (gameState.mode === 'TUTORIAL') {
            const id = instanceId || card.id;
            if (!tutorial.isInteractionAllowed(id)) return;
        }

        if (gameState.mode === 'SANDBOX' && !gameState.isSandboxRun) {
             setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
             return;
        }
        const activePid = actions.getActiveDecisionPlayerId(gameState);
        if (ownerId !== activePid) return;

        if (gameState.players[activePid].isCpu) return;

        if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
        else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
        else { return; }
        setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
        e.stopPropagation();
    };

    const handleDrop = (e: MouseEvent) => {
        if (!dragState || !gameState) return;
        const elements = document.elementsFromPoint(e.clientX, e.clientY);
        const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');
        if (!targetElement) {
             setDragState(null);
             return;
        }

        if (dragState.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetElement.id === 'field-area' || targetInstanceId) { 
                const player = gameState.players[gameState.turnPlayer];
                const untappedRes = player.resources.filter((r: any) => !r.isTapped).length;
                if (untappedRes < dragState.cardObj.cost) { 
                    actions.setGameState((prev: any) => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") })); 
                } else {
                    if (dragState.cardObj.rank === 'Q' || dragState.cardObj.rank === 'K') {
                        if (targetInstanceId) {
                            let targetOwnerId = -1;
                            gameState.players.forEach((p: any) => { if (p.field.some((f: any) => f.instanceId === targetInstanceId)) targetOwnerId = p.id; });
                            if (targetOwnerId !== -1) actions.playCard(dragState.cardObj, targetInstanceId, targetOwnerId);
                        }
                    } else { 
                        actions.playCard(dragState.cardObj); 
                    }
                    if (gameState.mode === 'TUTORIAL') {
                         tutorial.advanceTutorialStep('PLAY_CARD', dragState.cardObj.id);
                    }
                }
            }
        }
        else if (dragState.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
            const targetInstanceId = targetElement.getAttribute('data-instance-id');
            if (targetInstanceId && dragState.instanceId) { 
                 const blockerInstanceId = dragState.instanceId;
                 const attackerInstanceId = targetInstanceId;

                 actions.setGameState((prev: any) => {
                    if (!prev) return null;
                    if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;
                    const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
                    const blocker = defP.field.find((f: any) => f.instanceId === blockerInstanceId);
                    const attacker = prev.players[prev.turnPlayer].field.find((f: any) => f.instanceId === attackerInstanceId);
                    if (!blocker || !attacker || blocker.isTapped) return prev;
                    if (!canBlock(attacker, blocker)) return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
                    const newBlocks = { ...prev.pendingBlocks };
                    newBlocks[blockerInstanceId] = attackerInstanceId;
                    return { ...prev, pendingBlocks: newBlocks };
                });

                if (gameState.mode === 'TUTORIAL') tutorial.advanceTutorialStep('DECLARE_BLOCK', blockerInstanceId);
            }
        }
        setDragState(null);
    };

    const handleConfirmInitSelection = async () => {
         const activeId = actions.getActiveDecisionPlayerId(gameState!);
         if (gameState?.mode === 'TUTORIAL') {
             if (!tutorial.isInteractionAllowed('btn-confirm-init')) return;
             tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-init');
         }

         const p = gameState!.players[activeId];
         const selectedCards = p.hand.filter((c: any) => gameState!.initSelectedIds.includes(c.id));
         const resContainer = document.getElementById(`resource-container-${activeId}`);

         if (resContainer) {
             const resRect = resContainer.getBoundingClientRect();
             const animations = selectedCards.map((c: any) => {
                 const el = document.getElementById(c.id);
                 if (el) return effects.triggerFlyer(c, el.getBoundingClientRect(), resRect);
                 return Promise.resolve();
             });
             await Promise.all(animations);
         }

         actions.setGameState((prev: any) => {
            if (!prev) return null;
            const p = prev.players[activeId];
            const selected = p.hand.filter((c: any) => prev.initSelectedIds.includes(c.id));
            const remaining = p.hand.filter((c: any) => !prev.initSelectedIds.includes(c.id));
            p.hand = remaining;
            selected.forEach((c: any) => p.resources.push(createFieldCard(c, p.id)));
            const otherId = activeId === 0 ? 1 : 0;
            const other = prev.players[otherId];
            let nextState = { ...prev, initSelectedIds: [] };
            let gameStarting = false;

            // Simplified Start Logic: If the other player has resources, start. If not, swap.
            // This works for CPU vs CPU to avoid infinite loops.
            if (other.resources.length >= 3) {
                nextState.logs = addLog(nextState, "Battle Commencing!");
                nextState.phase = Phase.UPKEEP; 
                nextState.turnPlayer = prev.startingPlayerId;
                gameStarting = true;
                setTimeout(() => actions.advancePhase(Phase.UPKEEP, nextState), 500);
            } else {
                nextState.turnPlayer = otherId;
                nextState.logs = addLog(nextState, `${other.name}'s turn to setup.`);
            }

            if (gameStarting) setTimeout(() => effects.setShowTurnAnim(true), 100);
            return nextState;
         });
    };

    const handlePhaseAction = (action: 'ATTACK_PHASE' | 'END_TURN' | 'CONFIRM_ATTACK' | 'CONFIRM_BLOCK' | 'ADD_RESOURCE' | 'SWAP_RESOURCE' | 'CANCEL_RESOURCE' | 'CONFIRM_INIT') => {
        if(action === 'ATTACK_PHASE') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-attack-phase')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-attack-phase');
             }
             actions.advancePhase(Phase.ATTACK_DECLARE);
        }
        else if (action === 'END_TURN') {
             if (!tutorial.isInteractionAllowed('btn-end-turn')) return;
             ui.setShowEndTurnModal(true);
        }
        else if (action === 'CONFIRM_ATTACK') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-confirm-attackers')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-attackers');
             }
             actions.confirmAttack();
        }
        else if (action === 'CONFIRM_BLOCK') {
             if (gameState?.mode === 'TUTORIAL') {
                  if (!tutorial.isInteractionAllowed('btn-confirm-blocks') && !tutorial.isInteractionAllowed('btn-tutorial-next')) return;
                  tutorial.advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-blocks');
             }
             actions.confirmBlocks();
        }
        else if (action === 'ADD_RESOURCE') actions.advancePhase(Phase.RESOURCE_ADD_SELECT);
        else if (action === 'SWAP_RESOURCE') actions.advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
        else if (action === 'CANCEL_RESOURCE') actions.setGameState((prev: any) => prev ? { ...prev, phase: Phase.RESOURCE_START, selectedCardId: null } : null);
        else if (action === 'CONFIRM_INIT') handleConfirmInitSelection();
    };

    return {
        dragState, setDragState,
        handleCardClick,
        handleDragStart,
        handleDrop,
        handlePhaseAction,
        handleConfirmInitSelection // Exported for AI use
    };
};

import { useState, useCallback } from 'react';
import { Card, FlyingCard, FlyingText } from '../types';
import { generateId } from '../utils/core';

interface DamageAnimInstance {
    id: string;
    val: number;
    playerId: number;
    onApply?: () => void;
}

export const useGameEffects = () => {
    const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
    const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);
    const [explosions, setExplosions] = useState<{ id: string, x: number, y: number }[]>([]);
    const [damageAnims, setDamageAnims] = useState<DamageAnimInstance[]>([]);
    const [specialAnim, setSpecialAnim] = useState<{ type: 'K'|'Q'|'J', card: Card, targetRect?: DOMRect } | null>(null);
    const [showTurnAnim, setShowTurnAnim] = useState(false);

    const triggerFlyer = useCallback(async (card: Card, startRect: DOMRect, targetRect: DOMRect): Promise<void> => {
        return new Promise(resolve => {
            const id = generateId();
            const newFly: FlyingCard = {
                id, card, 
                startX: startRect.left, 
                startY: startRect.top, 
                targetX: targetRect.left + targetRect.width / 2 - 20, 
                targetY: targetRect.top + targetRect.height / 2 - 30
            };
            setFlyingCards(prev => [...prev, newFly]);
            setTimeout(() => { 
                setFlyingCards(prev => prev.filter(f => f.id !== id)); 
                resolve(); 
            }, 600);
        });
    }, []);

    const triggerExplosion = useCallback((instanceId: string) => {
        const el = document.getElementById(instanceId);
        if (el) {
            const rect = el.getBoundingClientRect();
            setExplosions(prev => [...prev, { id: generateId(), x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }]);
        }
    }, []);

    const removeExplosion = useCallback((id: string) => {
        setExplosions(prev => prev.filter(e => e.id !== id));
    }, []);

    const addDamageAnim = useCallback((val: number, playerId: number, onApply?: () => void) => {
        setDamageAnims(prev => [...prev, { id: generateId(), val, playerId, onApply }]);
    }, []);

    return {
        flyingTexts, setFlyingTexts,
        flyingCards, triggerFlyer,
        explosions, triggerExplosion, removeExplosion,
        damageAnims, setDamageAnims, addDamageAnim,
        specialAnim, setSpecialAnim,
        showTurnAnim, setShowTurnAnim
    };
};

import React, { useEffect } from 'react';
import { Phase, GameMode } from './types';
import { addLog } from './utils/core';
import { createFieldCard } from './utils/rules';
import { RotateCcw, Play, Edit3, Trash2, GraduationCap } from 'lucide-react';
import { sortHand } from './utils/cards';

// Imported Components
import { CoinFlipOverlay } from './components/overlays/CoinFlipOverlay';
import { TurnChangeOverlay } from './components/overlays/TurnChangeOverlay';
import { TutorialOverlay } from './components/overlays/TutorialOverlay';
import { Confetti, Explosion, DamageOverlay } from './components/effects/VisualEffects';
import { Flyer, SpecialCardAnimation } from './components/effects/GameAnimations';
import { MainMenu } from './components/screens/MainMenu';
import { SandboxTools } from './components/tools/SandboxTools';
import { EndTurnModal, ResignModal, QuitModal, PauseMenu } from './components/modals/GameModals';
import { DiscardModal } from './components/modals/DiscardModal';
import { MobileLayout } from './components/game/MobileLayout';
import { DesktopLayout } from './components/game/DesktopLayout';

// Hooks
import { useGameRefs } from './hooks/useGameRefs';
import { useGameEffects } from './hooks/useGameEffects';
import { useGameUI } from './hooks/useGameUI';
import { useGameState } from './hooks/useGameState';
import { useTutorial } from './hooks/useTutorial';
import { useGameAI } from './hooks/useGameAI';
import { useGameInteractions } from './hooks/useGameInteractions';

export const App: React.FC = () => {
  const refs = useGameRefs();
  const effects = useGameEffects();
  const ui = useGameUI();

  const { 
    gameState, setGameState, gameStateRef,
    startGame, drawCards, playCard, advancePhase, 
    performEndTurn, confirmAttack, confirmBlocks, 
    isDrawingInitialRef, getActiveDecisionPlayerId 
  } = useGameState({ effects, refs, autoSort: ui.autoSort });

  const { advanceTutorialStep, handleTutorialNext, isInteractionAllowed, handleGlobalClick } = useTutorial({
      gameState,
      setGameState,
      gameStateRef,
      performEndTurn,
      confirmBlocks
  });

  const interactions = useGameInteractions(gameState, {
      setGameState,
      gameStateRef,
      getActiveDecisionPlayerId,
      drawCards,
      playCard,
      advancePhase,
      confirmAttack,
      confirmBlocks
  }, effects, {
      isInteractionAllowed,
      advanceTutorialStep
  }, ui, refs);

  // Initialize AI Hook
  useGameAI({
      gameState,
      gameStateRef,
      actions: {
          setGameState,
          advancePhase,
          performEndTurn,
          playCard,
          confirmAttack,
          confirmBlocks,
          handleCardClick: interactions.handleCardClick,
          handleConfirmInitSelection: interactions.handleConfirmInitSelection,
          getActiveDecisionPlayerId
      },
      isCoinFlipping: ui.isCoinFlipping,
      showMenu: ui.showMenu,
      showTurnAnim: effects.showTurnAnim
  });

  // --- Handlers wrapping UI logic ---
  const handleModeSelect = (mode: GameMode) => {
      if (mode === 'SANDBOX') { startGame('SANDBOX', { p1: false, p2: false }); } 
      else if (mode === 'TUTORIAL') { ui.setMenuStep('TUTORIAL_MENU'); }
      else { ui.setSelectedMode(mode); ui.setMenuStep('PLAYERS'); }
  };

  const startLesson = (lessonId: string) => { startGame('TUTORIAL', { p1: false, p2: true }, lessonId); };
  const handleStartGameClick = (isCpu: boolean) => { if (ui.selectedMode) startGame(ui.selectedMode, { p1: false, p2: isCpu }); };
  const handleSpectateClick = () => { if (ui.selectedMode) startGame(ui.selectedMode, { p1: true, p2: true }); };

  const handleQuitToTitle = () => {
      const isTutorial = gameState?.mode === 'TUTORIAL';
      setGameState(null);
      ui.resetModals();
      ui.setMenuStep(isTutorial ? 'TUTORIAL_MENU' : 'MODE');
  };

  const handleResign = () => {
      if (!gameState) return;
      setGameState(prev => {
          if(!prev) return null;
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      ui.resetModals();
  };

  const executeCardAction = (action: 'TAP' | 'DELETE') => {
      if (!ui.cardActionTarget) return;
      setGameState(prev => {
          if(!prev) return null;
          const nextState = { ...prev, players: [...prev.players] };
          const p = nextState.players.find(pl => pl.id === ui.cardActionTarget!.ownerId)!;
          if (ui.cardActionTarget!.loc === 'HAND') {
              if (action === 'DELETE') { p.hand = p.hand.filter(c => c.id !== ui.cardActionTarget!.card.id); }
          } else if (ui.cardActionTarget!.loc === 'FIELD') {
              if (action === 'DELETE') { p.field = p.field.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
              else if (action === 'TAP') { const fc = p.field.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          } else if (ui.cardActionTarget!.loc === 'RESOURCE') {
               if (action === 'DELETE') { p.resources = p.resources.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
               else if (action === 'TAP') { const fc = p.resources.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          }
          return nextState;
      });
      ui.setCardActionTarget(null);
  };

  const startPlayFromHere = (isCpu: boolean) => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'STREET', phase: Phase.MAIN, isSandboxRun: true, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu } : p) };
      });
      ui.setShowPlaySetup(false); ui.setSandboxToolsOpen(false);
  };

  const returnToSandbox = () => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'SANDBOX', isSandboxRun: false, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu: false } : p) };
      });
      ui.setSandboxToolsOpen(true);
  };

  // Initial Draw Effect (Moved logic slightly to ensure it runs once)
  useEffect(() => {
    if (gameState && gameState.mode !== 'SANDBOX' && gameState.mode !== 'TUTORIAL' && gameState.phase === Phase.INIT_SELECT && !ui.isCoinFlipping) {
      if (!isDrawingInitialRef.current) {
        const p1 = gameState.players[0];
        const p2 = gameState.players[1];
        if (p1.hand.length === 0 || p2.hand.length === 0) {
             isDrawingInitialRef.current = true;
             (async () => {
                 await drawCards(0, 8);
                 await drawCards(1, 8);
                 setGameState(prev => prev ? { ...prev, logs: addLog(prev, "Deployment Phase: Select 3 resources.") } : null);
                 isDrawingInitialRef.current = false;
             })();
        }
      }
    }
  }, [gameState?.phase, ui.isCoinFlipping, gameState?.mode]);

  if (!gameState) {
      return (
        <div className="relative flex flex-col items-center justify-center h-screen w-full bg-slate-950 overflow-hidden selection:bg-indigo-500/30">
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-black z-0"></div>
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] opacity-30 z-0"></div>
            <MainMenu 
                menuStep={ui.menuStep}
                setMenuStep={ui.setMenuStep}
                handleModeSelect={handleModeSelect}
                handleStartGameClick={handleStartGameClick}
                handleSpectateClick={handleSpectateClick}
                startLesson={startLesson}
            />
        </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const isHotseat = !gameState.players[1].isCpu || gameState.mode === 'SANDBOX';
  const viewPlayerId = isHotseat ? activeDecisionPlayerId : 0; 
  const bottomPlayer = gameState.players[viewPlayerId];
  const topPlayer = gameState.players[viewPlayerId === 0 ? 1 : 0];
  const isPlayerTurn = activeDecisionPlayerId === viewPlayerId;
  const isActivePlayerCpu = gameState.players[activeDecisionPlayerId].isCpu;
  const isInteractive = isPlayerTurn && !isActivePlayerCpu;
  const tutorialComplete = gameState.tutorialState?.completed;

  const gameHandlers = {
      onCardClick: interactions.handleCardClick,
      onDragStart: interactions.handleDragStart,
      onPhaseAction: interactions.handlePhaseAction,
      setViewingDiscard: ui.setViewingDiscard,
      setShowMenu: ui.setShowMenu,
      toggleLog: () => ui.setShowMobileLog(!ui.showMobileLog)
  };

  return (
    <div 
      className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" 
      ref={refs.containerRef}
      onMouseMove={(e) => {
          if (interactions.dragState) interactions.setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
      }}
      onMouseUp={(e) => interactions.handleDrop(e.nativeEvent)}
      onClick={handleGlobalClick}
    >
      {ui.isCoinFlipping && (
           <CoinFlipOverlay 
                p1Name={gameState.players[0].name} 
                p2Name={gameState.players[1].name} 
                onComplete={(winner) => {
                    setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null);
                    ui.setIsCoinFlipping(false);
                }} 
           />
      )}

      {gameState.tutorialState?.active && !tutorialComplete && gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex] && (
          <TutorialOverlay step={gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex]} onNext={handleTutorialNext} />
      )}

      {tutorialComplete && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <GraduationCap className="w-24 h-24 mx-auto text-emerald-500 animate-bounce" />
                  <h1 className="text-5xl md:text-7xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-500 drop-shadow-[0_0_25px_rgba(16,185,129,0.5)]">
                      TUTORIAL COMPLETE
                  </h1>
                  <h2 className="text-2xl text-slate-300">You have mastered the basics!</h2>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg font-bold text-xl shadow-lg shadow-emerald-500/30 transform transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                          <RotateCcw size={20} /> Return to Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState.isSandboxRun && (
          <div className="absolute top-16 left-4 z-50 animate-in fade-in slide-in-from-top">
              <button onClick={returnToSandbox} className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-lg font-bold shadow-lg flex items-center gap-2">
                  <RotateCcw size={18}/> Return to Sandbox
              </button>
          </div>
      )}

      {ui.showPlaySetup && (
          <div className="absolute inset-0 z-[100] bg-black/80 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 w-80">
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2"><Play size={20} className="text-emerald-400"/> Play Scenario</h3>
                  <div className="space-y-3">
                      <button onClick={() => startPlayFromHere(true)} className="w-full bg-slate-800 hover:bg-emerald-900/30 border border-slate-700 hover:border-emerald-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Edit3 size={18}/> Vs CPU
                      </button>
                      <button onClick={() => startPlayFromHere(false)} className="w-full bg-slate-800 hover:bg-amber-900/30 border border-slate-700 hover:border-amber-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Edit3 size={18}/> Hotseat
                      </button>
                  </div>
                  <button onClick={() => ui.setShowPlaySetup(false)} className="mt-4 text-slate-500 text-sm hover:text-white">Cancel</button>
              </div>
          </div>
      )}

      {ui.cardActionTarget && (
          <div className="absolute inset-0 z-[100] bg-black/50 flex items-center justify-center" onClick={() => ui.setCardActionTarget(null)}>
              <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 shadow-2xl transform scale-100 transition-transform" onClick={e => e.stopPropagation()}>
                  <div className="flex justify-center mb-4">
                      {/* Note: In a real refactor, createFieldCard logic might need to ensure Card is valid or reconstruct it */}
                      {/* Using safe access */}
                      <div className="w-32 h-44 bg-white rounded-md text-black flex items-center justify-center">
                          {ui.cardActionTarget.card.rank}{ui.cardActionTarget.card.suit}
                      </div>
                  </div>
                  <div className="flex gap-2 justify-center">
                      {ui.cardActionTarget.loc !== 'HAND' && (
                          <button onClick={() => executeCardAction('TAP')} className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                              <RotateCcw size={16}/> Tap/Untap
                          </button>
                      )}
                      <button onClick={() => executeCardAction('DELETE')} className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                          <Trash2 size={16}/> Remove
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState.mode === 'SANDBOX' && !gameState.isSandboxRun && !ui.sandboxToolsOpen && (
          <button 
            onClick={() => ui.setSandboxToolsOpen(true)} 
            className="absolute top-20 right-4 z-50 bg-slate-800 p-3 rounded-full border border-slate-600 shadow-xl hover:bg-slate-700 text-amber-400"
          >
              <Edit3 size={24} />
          </button>
      )}

      {ui.sandboxToolsOpen && (
          <SandboxTools 
              gameState={gameState}
              setGameState={setGameState}
              sandboxSearchTerm={ui.sandboxSearchTerm}
              setSandboxSearchTerm={ui.setSandboxSearchTerm}
              sandboxTargetPlayer={ui.sandboxTargetPlayer}
              setSandboxTargetPlayer={ui.setSandboxTargetPlayer}
              selectedSandboxCard={ui.selectedSandboxCard}
              setSelectedSandboxCard={ui.setSelectedSandboxCard}
              setSandboxToolsOpen={ui.setSandboxToolsOpen}
              setShowPlaySetup={ui.setShowPlaySetup}
          />
      )}

      {effects.showTurnAnim && (
          <TurnChangeOverlay 
              playerName={gameState.players[gameState.turnPlayer].name}
              turnCount={gameState.turnCount}
              onComplete={() => effects.setShowTurnAnim(false)}
          />
      )}

      {gameState.phase === Phase.GAME_OVER && !tutorialComplete && gameState.mode !== 'TUTORIAL' && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <h1 className="text-6xl md:text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 drop-shadow-[0_0_25px_rgba(234,179,8,0.5)] animate-bounce">
                      GAME OVER
                  </h1>
                  <h2 className="text-3xl font-bold text-white drop-shadow-md">
                      {gameState.winner !== null ? `${gameState.players[gameState.winner].name} Wins!` : "It's a Draw!"}
                  </h2>
                  <div className="text-xl text-slate-400 font-title uppercase tracking-widest mt-2">
                      Total Turns: {gameState.turnCount}
                  </div>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-bold text-xl shadow-lg shadow-indigo-500/30 transform transition-all hover:scale-105 active:scale-95">
                          Rematch / Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      <EndTurnModal show={ui.showEndTurnModal} onCancel={() => ui.setShowEndTurnModal(false)} onConfirm={() => { ui.setShowEndTurnModal(false); performEndTurn(); }} />
      <ResignModal show={ui.showResignModal} onCancel={() => ui.setShowResignModal(false)} onConfirm={handleResign} />
      <QuitModal show={ui.showQuitModal} onCancel={() => ui.setShowQuitModal(false)} onConfirm={handleQuitToTitle} />
      <PauseMenu 
        show={ui.showMenu} 
        onResume={() => ui.setShowMenu(false)} 
        onResign={() => ui.setShowResignModal(true)} 
        onQuit={() => ui.setShowQuitModal(true)} 
        autoSort={ui.autoSort} 
        onToggleSort={() => ui.toggleAutoSort(setGameState, getActiveDecisionPlayerId)} 
      />

      <DiscardModal 
        viewingDiscard={ui.viewingDiscard} 
        players={gameState.players} 
        onClose={() => ui.setViewingDiscard(null)} 
        mode={gameState.mode} 
      />

      {effects.specialAnim && <SpecialCardAnimation type={effects.specialAnim.type} card={effects.specialAnim.card} targetRect={effects.specialAnim.targetRect} onComplete={() => effects.setSpecialAnim(null)} />}

      {effects.flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {effects.flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {effects.explosions.map(e => (
          <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => effects.removeExplosion(e.id)} />
      ))}

      {effects.damageAnims.map(da => (
          <DamageOverlay 
            key={da.id}
            dmg={da.val} 
            targetRef={da.playerId === topPlayer.id ? refs.lifeIconRef : refs.bottomLifeRef}
            onComplete={() => effects.setDamageAnims(prev => prev.filter(a => a.id !== da.id))}
            onImpact={da.onApply}
          />
      ))}

      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2} y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2} y2={aRect.top + aRect.height/2}
                        stroke="#3b82f6" strokeWidth="4" strokeDasharray="0" className="opacity-70"
                      />
                  );
              }
              return null;
          })}
          {interactions.dragState?.sourceType === 'FIELD' && interactions.dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(interactions.dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={interactions.dragState.currentX} y2={interactions.dragState.currentY}
                                stroke="#3b82f6" strokeWidth="4" strokeDasharray="5" className="opacity-70"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {ui.isMobile ? (
          <MobileLayout 
            gameState={gameState}
            topPlayer={topPlayer}
            bottomPlayer={bottomPlayer}
            activeDecisionPlayerId={activeDecisionPlayerId}
            isInteractive={isInteractive}
            dragState={interactions.dragState}
            handlers={gameHandlers}
            refs={refs}
            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      ) : (
          <DesktopLayout 
            gameState={gameState}
            topPlayer={topPlayer}
            bottomPlayer={bottomPlayer}
            activeDecisionPlayerId={activeDecisionPlayerId}
            isInteractive={isInteractive}
            dragState={interactions.dragState}
            handlers={gameHandlers}
            refs={refs}
            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      )}
    </div>
  );
};

import React, { useEffect } from 'react';
import { Phase, GameMode } from './types';
import { addLog } from './utils/core';
import { createFieldCard } from './utils/rules';
import { RotateCcw, Play, Edit3, Trash2, GraduationCap } from 'lucide-react';
import { sortHand } from './utils/cards';

// Imported Components
import { CoinFlipOverlay } from './components/overlays/CoinFlipOverlay';
import { TurnChangeOverlay } from './components/overlays/TurnChangeOverlay';
import { TutorialOverlay } from './components/overlays/TutorialOverlay';
import { Confetti, Explosion, DamageOverlay } from './components/effects/VisualEffects';
import { Flyer, SpecialCardAnimation } from './components/effects/GameAnimations';
import { MainMenu } from './components/screens/MainMenu';
import { SandboxTools } from './components/tools/SandboxTools';
import { EndTurnModal, ResignModal, QuitModal, PauseMenu } from './components/modals/GameModals';
import { DiscardModal } from './components/modals/DiscardModal';
import { MobileLayout } from './components/game/MobileLayout';
import { DesktopLayout } from './components/game/DesktopLayout';

// Hooks
import { useGameRefs } from './hooks/useGameRefs';
import { useGameEffects } from './hooks/useGameEffects';
import { useGameUI } from './hooks/useGameUI';
import { useGameState } from './hooks/useGameState';
import { useTutorial } from './hooks/useTutorial';
import { useGameAI } from './hooks/useGameAI';
import { useGameInteractions } from './hooks/useGameInteractions';

export const App: React.FC = () => {
  const refs = useGameRefs();
  const effects = useGameEffects();
  const ui = useGameUI();

  const { 
    gameState, setGameState, gameStateRef,
    startGame, drawCards, playCard, advancePhase, 
    performEndTurn, confirmAttack, confirmBlocks, 
    isDrawingInitialRef, getActiveDecisionPlayerId 
  } = useGameState({ effects, refs, autoSort: ui.autoSort });

  const { advanceTutorialStep, handleTutorialNext, isInteractionAllowed, handleGlobalClick } = useTutorial({
      gameState,
      setGameState,
      gameStateRef,
      performEndTurn,
      confirmBlocks
  });

  const interactions = useGameInteractions(gameState, {
      setGameState,
      gameStateRef,
      getActiveDecisionPlayerId,
      drawCards,
      playCard,
      advancePhase,
      confirmAttack,
      confirmBlocks
  }, effects, {
      isInteractionAllowed,
      advanceTutorialStep
  }, ui, refs);

  // Initialize AI Hook
  useGameAI({
      gameState,
      gameStateRef,
      actions: {
          setGameState,
          advancePhase,
          performEndTurn,
          playCard,
          confirmAttack,
          confirmBlocks,
          handleCardClick: interactions.handleCardClick,
          handleConfirmInitSelection: interactions.handleConfirmInitSelection,
          getActiveDecisionPlayerId
      },
      isCoinFlipping: ui.isCoinFlipping,
      showMenu: ui.showMenu,
      showTurnAnim: effects.showTurnAnim
  });

  // --- Handlers wrapping UI logic ---
  const handleModeSelect = (mode: GameMode) => {
      if (mode === 'SANDBOX') { startGame('SANDBOX', { p1: false, p2: false }); } 
      else if (mode === 'TUTORIAL') { ui.setMenuStep('TUTORIAL_MENU'); }
      else { ui.setSelectedMode(mode); ui.setMenuStep('PLAYERS'); }
  };

  const startLesson = (lessonId: string) => { startGame('TUTORIAL', { p1: false, p2: true }, lessonId); };
  const handleStartGameClick = (isCpu: boolean) => { if (ui.selectedMode) startGame(ui.selectedMode, { p1: false, p2: isCpu }); };
  const handleSpectateClick = () => { if (ui.selectedMode) startGame(ui.selectedMode, { p1: true, p2: true }); };

  const handleQuitToTitle = () => {
      const isTutorial = gameState?.mode === 'TUTORIAL';
      setGameState(null);
      ui.resetModals();
      ui.setMenuStep(isTutorial ? 'TUTORIAL_MENU' : 'MODE');
  };

  const handleResign = () => {
      if (!gameState) return;
      setGameState(prev => {
          if(!prev) return null;
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      ui.resetModals();
  };

  const executeCardAction = (action: 'TAP' | 'DELETE') => {
      if (!ui.cardActionTarget) return;
      setGameState(prev => {
          if(!prev) return null;
          const nextState = { ...prev, players: [...prev.players] };
          const p = nextState.players.find(pl => pl.id === ui.cardActionTarget!.ownerId)!;
          if (ui.cardActionTarget!.loc === 'HAND') {
              if (action === 'DELETE') { p.hand = p.hand.filter(c => c.id !== ui.cardActionTarget!.card.id); }
          } else if (ui.cardActionTarget!.loc === 'FIELD') {
              if (action === 'DELETE') { p.field = p.field.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
              else if (action === 'TAP') { const fc = p.field.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          } else if (ui.cardActionTarget!.loc === 'RESOURCE') {
               if (action === 'DELETE') { p.resources = p.resources.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
               else if (action === 'TAP') { const fc = p.resources.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          }
          return nextState;
      });
      ui.setCardActionTarget(null);
  };

  const startPlayFromHere = (isCpu: boolean) => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'STREET', phase: Phase.MAIN, isSandboxRun: true, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu } : p) };
      });
      ui.setShowPlaySetup(false); ui.setSandboxToolsOpen(false);
  };

  const returnToSandbox = () => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'SANDBOX', isSandboxRun: false, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu: false } : p) };
      });
      ui.setSandboxToolsOpen(true);
  };

  // Initial Draw Effect (Moved logic slightly to ensure it runs once)
  useEffect(() => {
    if (gameState && gameState.mode !== 'SANDBOX' && gameState.mode !== 'TUTORIAL' && gameState.phase === Phase.INIT_SELECT && !ui.isCoinFlipping) {
      if (!isDrawingInitialRef.current) {
        const p1 = gameState.players[0];
        const p2 = gameState.players[1];
        if (p1.hand.length === 0 || p2.hand.length === 0) {
             isDrawingInitialRef.current = true;
             // Add a small delay to ensure refs/layout are stable
             setTimeout(() => {
                 (async () => {
                     await drawCards(0, 8);
                     await drawCards(1, 8);
                     setGameState(prev => prev ? { ...prev, logs: addLog(prev, "Deployment Phase: Select 3 resources.") } : null);
                     isDrawingInitialRef.current = false;
                 })();
             }, 200);
        }
      }
    }
  }, [gameState?.phase, ui.isCoinFlipping, gameState?.mode]);

  if (!gameState) {
      return (
        <div className="relative flex flex-col items-center justify-center h-screen w-full bg-slate-950 overflow-hidden selection:bg-indigo-500/30">
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-black z-0"></div>
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] opacity-30 z-0"></div>
            <MainMenu 
                menuStep={ui.menuStep}
                setMenuStep={ui.setMenuStep}
                handleModeSelect={handleModeSelect}
                handleStartGameClick={handleStartGameClick}
                handleSpectateClick={handleSpectateClick}
                startLesson={startLesson}
            />
        </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const isHotseat = !gameState.players[1].isCpu || gameState.mode === 'SANDBOX';
  const viewPlayerId = isHotseat ? activeDecisionPlayerId : 0; 
  const bottomPlayer = gameState.players[viewPlayerId];
  const topPlayer = gameState.players[viewPlayerId === 0 ? 1 : 0];
  const isPlayerTurn = activeDecisionPlayerId === viewPlayerId;
  const isActivePlayerCpu = gameState.players[activeDecisionPlayerId].isCpu;
  const isInteractive = isPlayerTurn && !isActivePlayerCpu;
  const tutorialComplete = gameState.tutorialState?.completed;

  const gameHandlers = {
      onCardClick: interactions.handleCardClick,
      onDragStart: interactions.handleDragStart,
      onPhaseAction: interactions.handlePhaseAction,
      setViewingDiscard: ui.setViewingDiscard,
      setShowMenu: ui.setShowMenu,
      toggleLog: () => ui.setShowMobileLog(!ui.showMobileLog)
  };

  return (
    <div 
      className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" 
      ref={refs.containerRef}
      onMouseMove={(e) => {
          if (interactions.dragState) interactions.setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
      }}
      onMouseUp={(e) => interactions.handleDrop(e.nativeEvent)}
      onClick={handleGlobalClick}
    >
      {ui.isCoinFlipping && (
           <CoinFlipOverlay 
                p1Name={gameState.players[0].name} 
                p2Name={gameState.players[1].name} 
                onComplete={(winner) => {
                    setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null);
                    ui.setIsCoinFlipping(false);
                }} 
           />
      )}

      {gameState.tutorialState?.active && !tutorialComplete && gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex] && (
          <TutorialOverlay step={gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex]} onNext={handleTutorialNext} />
      )}

      {tutorialComplete && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <GraduationCap className="w-24 h-24 mx-auto text-emerald-500 animate-bounce" />
                  <h1 className="text-5xl md:text-7xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-500 drop-shadow-[0_0_25px_rgba(16,185,129,0.5)]">
                      TUTORIAL COMPLETE
                  </h1>
                  <h2 className="text-2xl text-slate-300">You have mastered the basics!</h2>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg font-bold text-xl shadow-lg shadow-emerald-500/30 transform transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                          <RotateCcw size={20} /> Return to Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState.isSandboxRun && (
          <div className="absolute top-16 left-4 z-50 animate-in fade-in slide-in-from-top">
              <button onClick={returnToSandbox} className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-lg font-bold shadow-lg flex items-center gap-2">
                  <RotateCcw size={18}/> Return to Sandbox
              </button>
          </div>
      )}

      {ui.showPlaySetup && (
          <div className="absolute inset-0 z-[100] bg-black/80 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 w-80">
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2"><Play size={20} className="text-emerald-400"/> Play Scenario</h3>
                  <div className="space-y-3">
                      <button onClick={() => startPlayFromHere(true)} className="w-full bg-slate-800 hover:bg-emerald-900/30 border border-slate-700 hover:border-emerald-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Edit3 size={18}/> Vs CPU
                      </button>
                      <button onClick={() => startPlayFromHere(false)} className="w-full bg-slate-800 hover:bg-amber-900/30 border border-slate-700 hover:border-amber-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Edit3 size={18}/> Hotseat
                      </button>
                  </div>
                  <button onClick={() => ui.setShowPlaySetup(false)} className="mt-4 text-slate-500 text-sm hover:text-white">Cancel</button>
              </div>
          </div>
      )}

      {ui.cardActionTarget && (
          <div className="absolute inset-0 z-[100] bg-black/50 flex items-center justify-center" onClick={() => ui.setCardActionTarget(null)}>
              <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 shadow-2xl transform scale-100 transition-transform" onClick={e => e.stopPropagation()}>
                  <div className="flex justify-center mb-4">
                      {/* Note: In a real refactor, createFieldCard logic might need to ensure Card is valid or reconstruct it */}
                      {/* Using safe access */}
                      <div className="w-32 h-44 bg-white rounded-md text-black flex items-center justify-center">
                          {ui.cardActionTarget.card.rank}{ui.cardActionTarget.card.suit}
                      </div>
                  </div>
                  <div className="flex gap-2 justify-center">
                      {ui.cardActionTarget.loc !== 'HAND' && (
                          <button onClick={() => executeCardAction('TAP')} className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                              <RotateCcw size={16}/> Tap/Untap
                          </button>
                      )}
                      <button onClick={() => executeCardAction('DELETE')} className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                          <Trash2 size={16}/> Remove
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState.mode === 'SANDBOX' && !gameState.isSandboxRun && !ui.sandboxToolsOpen && (
          <button 
            onClick={() => ui.setSandboxToolsOpen(true)} 
            className="absolute top-20 right-4 z-50 bg-slate-800 p-3 rounded-full border border-slate-600 shadow-xl hover:bg-slate-700 text-amber-400"
          >
              <Edit3 size={24} />
          </button>
      )}

      {ui.sandboxToolsOpen && (
          <SandboxTools 
              gameState={gameState}
              setGameState={setGameState}
              sandboxSearchTerm={ui.sandboxSearchTerm}
              setSandboxSearchTerm={ui.setSandboxSearchTerm}
              sandboxTargetPlayer={ui.sandboxTargetPlayer}
              setSandboxTargetPlayer={ui.setSandboxTargetPlayer}
              selectedSandboxCard={ui.selectedSandboxCard}
              setSelectedSandboxCard={ui.setSelectedSandboxCard}
              setSandboxToolsOpen={ui.setSandboxToolsOpen}
              setShowPlaySetup={ui.setShowPlaySetup}
          />
      )}

      {effects.showTurnAnim && (
          <TurnChangeOverlay 
              playerName={gameState.players[gameState.turnPlayer].name}
              turnCount={gameState.turnCount}
              onComplete={() => effects.setShowTurnAnim(false)}
          />
      )}

      {gameState.phase === Phase.GAME_OVER && !tutorialComplete && gameState.mode !== 'TUTORIAL' && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <h1 className="text-6xl md:text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 drop-shadow-[0_0_25px_rgba(234,179,8,0.5)] animate-bounce">
                      GAME OVER
                  </h1>
                  <h2 className="text-3xl font-bold text-white drop-shadow-md">
                      {gameState.winner !== null ? `${gameState.players[gameState.winner].name} Wins!` : "It's a Draw!"}
                  </h2>
                  <div className="text-xl text-slate-400 font-title uppercase tracking-widest mt-2">
                      Total Turns: {gameState.turnCount}
                  </div>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-bold text-xl shadow-lg shadow-indigo-500/30 transform transition-all hover:scale-105 active:scale-95">
                          Rematch / Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      <EndTurnModal show={ui.showEndTurnModal} onCancel={() => ui.setShowEndTurnModal(false)} onConfirm={() => { 
          ui.setShowEndTurnModal(false); 
          performEndTurn(); 
          if(gameState.mode === 'TUTORIAL') advanceTutorialStep('CLICK_UI_BUTTON', 'btn-end-turn-modal-confirm');
      }} />
      <ResignModal show={ui.showResignModal} onCancel={() => ui.setShowResignModal(false)} onConfirm={handleResign} />
      <QuitModal show={ui.showQuitModal} onCancel={() => ui.setShowQuitModal(false)} onConfirm={handleQuitToTitle} />
      <PauseMenu 
        show={ui.showMenu} 
        onResume={() => ui.setShowMenu(false)} 
        onResign={() => ui.setShowResignModal(true)} 
        onQuit={() => ui.setShowQuitModal(true)} 
        autoSort={ui.autoSort} 
        onToggleSort={() => ui.toggleAutoSort(setGameState, getActiveDecisionPlayerId)} 
      />

      <DiscardModal 
        viewingDiscard={ui.viewingDiscard} 
        players={gameState.players} 
        onClose={() => ui.setViewingDiscard(null)} 
        mode={gameState.mode} 
      />

      {effects.specialAnim && <SpecialCardAnimation type={effects.specialAnim.type} card={effects.specialAnim.card} targetRect={effects.specialAnim.targetRect} onComplete={() => effects.setSpecialAnim(null)} />}

      {effects.flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {effects.flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {effects.explosions.map(e => (
          <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => effects.removeExplosion(e.id)} />
      ))}

      {effects.damageAnims.map(da => (
          <DamageOverlay 
            key={da.id}
            dmg={da.val} 
            targetRef={da.playerId === topPlayer.id ? refs.lifeIconRef : refs.bottomLifeRef}
            onComplete={() => effects.setDamageAnims(prev => prev.filter(a => a.id !== da.id))}
            onImpact={da.onApply}
          />
      ))}

      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2} y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2} y2={aRect.top + aRect.height/2}
                        stroke="#3b82f6" strokeWidth="4" strokeDasharray="0" className="opacity-70"
                      />
                  );
              }
              return null;
          })}
          {interactions.dragState?.sourceType === 'FIELD' && interactions.dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(interactions.dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={interactions.dragState.currentX} y2={interactions.dragState.currentY}
                                stroke="#3b82f6" strokeWidth="4" strokeDasharray="5" className="opacity-70"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {ui.isMobile ? (
          <MobileLayout 
            gameState={gameState}
            topPlayer={topPlayer}
            bottomPlayer={bottomPlayer}
            activeDecisionPlayerId={activeDecisionPlayerId}
            isInteractive={isInteractive}
            dragState={interactions.dragState}
            handlers={gameHandlers}
            refs={refs}
            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      ) : (
          <DesktopLayout 
            gameState={gameState}
            topPlayer={topPlayer}
            bottomPlayer={bottomPlayer}
            activeDecisionPlayerId={activeDecisionPlayerId}
            isInteractive={isInteractive}
            dragState={interactions.dragState}
            handlers={gameHandlers}
            refs={refs}
            uiState={{ showMobileLog: ui.showMobileLog, showMenu: ui.showMenu }}
          />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';

const SUITS = ['♠', '♣', '♥', '♦'];

interface Particle {
    id: number;
    suit: string;
    isRed: boolean;
    x: number;
    y: number;
    size: number;
    duration: number;
    delay: number;
    opacity: number;
    rotation: number;
}

export const MainMenuBackground: React.FC = () => {
    const [particles, setParticles] = useState<Particle[]>([]);

    useEffect(() => {
        // Generate particles only on client side to avoid hydration mismatch
        const newParticles = Array.from({ length: 30 }).map((_, i) => {
            const suit = SUITS[Math.floor(Math.random() * SUITS.length)];
            const isRed = suit === '♥' || suit === '♦';
            return {
                id: i,
                suit,
                isRed,
                x: Math.random() * 100, // 0-100%
                y: Math.random() * 100, // 0-100%
                size: Math.random() * 6 + 3, // 3rem to 9rem
                duration: Math.random() * 30 + 20, // 20s to 50s
                delay: Math.random() * -30, // Negative delay to start mid-animation
                opacity: Math.random() * 0.15 + 0.05, // 0.05 to 0.20
                rotation: Math.random() * 360
            };
        });
        setParticles(newParticles);
    }, []);

    return (
        <div className="absolute inset-0 overflow-hidden pointer-events-none z-0 bg-slate-950">
            {/* Deep Background Gradient - Top Spotlight */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_-20%,_var(--tw-gradient-stops))] from-indigo-900/40 via-slate-950 to-black"></div>

            {/* Subtle Pattern Overlay */}
            <div className="absolute inset-0 opacity-[0.05]" 
                 style={{ 
                     backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%239C92AC' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")` 
                 }}
            ></div>

            {/* Floating Particles */}
            {particles.map((p) => (
                <div 
                    key={p.id}
                    className="absolute font-serif font-bold animate-float-slow"
                    style={{
                        left: `${p.x}%`,
                        top: `${p.y}%`,
                        fontSize: `${p.size}rem`,
                        color: p.isRed ? '#ef4444' : '#6366f1', // Red-500 or Indigo-500
                        opacity: p.opacity,
                        animationDuration: `${p.duration}s`,
                        animationDelay: `${p.delay}s`,
                        textShadow: p.isRed ? '0 0 40px rgba(220,38,38,0.6)' : '0 0 40px rgba(99,102,241,0.6)',
                        transform: `rotate(${p.rotation}deg)`,
                        filter: 'blur(1px)'
                    }}
                >
                    {p.suit}
                </div>
            ))}

            {/* Bottom Vignette to ensure text readability */}
            <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-black/40"></div>

            <style>{`
                @keyframes float-slow {
                    0% { transform: translateY(0) rotate(0deg) scale(1); }
                    33% { transform: translateY(-40px) rotate(5deg) scale(1.1); }
                    66% { transform: translateY(20px) rotate(-5deg) scale(0.95); }
                    100% { transform: translateY(0) rotate(0deg) scale(1); }
                }
                .animate-float-slow {
                    animation-name: float-slow;
                    animation-timing-function: ease-in-out;
                    animation-iteration-count: infinite;
                }
            `}</style>
        </div>
    );
};

import React, { useEffect } from 'react';
import { Phase, GameMode } from './types';
import { addLog } from './utils/core';
import { createFieldCard } from './utils/rules';
import { RotateCcw, Play, Edit3, Trash2, GraduationCap } from 'lucide-react';
import { sortHand } from './utils/cards';

// Imported Components
import { CoinFlipOverlay } from './components/overlays/CoinFlipOverlay';
import { TurnChangeOverlay } from './components/overlays/TurnChangeOverlay';
import { TutorialOverlay } from './components/overlays/TutorialOverlay';
import { Confetti, Explosion, DamageOverlay } from './components/effects/VisualEffects';
import { Flyer, SpecialCardAnimation } from './components/effects/GameAnimations';
import { MainMenu } from './components/screens/MainMenu';
import { MainMenuBackground } from './components/effects/MainMenuBackground';
import { SandboxTools } from './components/tools/SandboxTools';
import { EndTurnModal, ResignModal, QuitModal, PauseMenu } from './components/modals/GameModals';
import { DiscardModal } from './components/modals/DiscardModal';
import { MobileLayout } from './components/game/MobileLayout';
import { DesktopLayout } from './components/game/DesktopLayout';

// Hooks
import { useGameRefs } from './hooks/useGameRefs';
import { useGameEffects } from './hooks/useGameEffects';
import { useGameUI } from './hooks/useGameUI';
import { useGameState } from './hooks/useGameState';
import { useTutorial } from './hooks/useTutorial';
import { useGameAI } from './hooks/useGameAI';
import { useGameInteractions } from './hooks/useGameInteractions';

export const App: React.FC = () => {
  const refs = useGameRefs();
  const effects = useGameEffects();
  const ui = useGameUI();

  const { 
    gameState, setGameState, gameStateRef,
    startGame, drawCards, playCard, advancePhase, 
    performEndTurn, confirmAttack, confirmBlocks, 
    isDrawingInitialRef, getActiveDecisionPlayerId 
  } = useGameState({ effects, refs, autoSort: ui.autoSort });

  const { advanceTutorialStep, handleTutorialNext, isInteractionAllowed, handleGlobalClick } = useTutorial({
      gameState,
      setGameState,
      gameStateRef,
      performEndTurn,
      confirmBlocks
  });

  const interactions = useGameInteractions(gameState, {
      setGameState,
      gameStateRef,
      getActiveDecisionPlayerId,
      drawCards,
      playCard,
      advancePhase,
      confirmAttack,
      confirmBlocks
  }, effects, {
      isInteractionAllowed,
      advanceTutorialStep
  }, ui, refs);

  // Initialize AI Hook
  useGameAI({
      gameState,
      gameStateRef,
      actions: {
          setGameState,
          advancePhase,
          performEndTurn,
          playCard,
          confirmAttack,
          confirmBlocks,
          handleCardClick: interactions.handleCardClick,
          handleConfirmInitSelection: interactions.handleConfirmInitSelection,
          getActiveDecisionPlayerId
      },
      isCoinFlipping: ui.isCoinFlipping,
      showMenu: ui.showMenu,
      showTurnAnim: effects.showTurnAnim
  });

  // --- Handlers wrapping UI logic ---
  const handleModeSelect = (mode: GameMode) => {
      if (mode === 'SANDBOX') { startGame('SANDBOX', { p1: false, p2: false }); } 
      else if (mode === 'TUTORIAL') { ui.setMenuStep('TUTORIAL_MENU'); }
      else { ui.setSelectedMode(mode); ui.setMenuStep('PLAYERS'); }
  };

  const startLesson = (lessonId: string) => { startGame('TUTORIAL', { p1: false, p2: true }, lessonId); };
  const handleStartGameClick = (isCpu: boolean) => { if (ui.selectedMode) startGame(ui.selectedMode, { p1: false, p2: isCpu }); };
  const handleSpectateClick = () => { if (ui.selectedMode) startGame(ui.selectedMode, { p1: true, p2: true }); };

  const handleQuitToTitle = () => {
      const isTutorial = gameState?.mode === 'TUTORIAL';
      setGameState(null);
      ui.resetModals();
      ui.setMenuStep(isTutorial ? 'TUTORIAL_MENU' : 'MODE');
  };

  const handleResign = () => {
      if (!gameState) return;
      setGameState(prev => {
          if(!prev) return null;
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      ui.resetModals();
  };

  const executeCardAction = (action: 'TAP' | 'DELETE') => {
      if (!ui.cardActionTarget) return;
      setGameState(prev => {
          if(!prev) return null;
          const nextState = { ...prev, players: [...prev.players] };
          const p = nextState.players.find(pl => pl.id === ui.cardActionTarget!.ownerId)!;
          if (ui.cardActionTarget!.loc === 'HAND') {
              if (action === 'DELETE') { p.hand = p.hand.filter(c => c.id !== ui.cardActionTarget!.card.id); }
          } else if (ui.cardActionTarget!.loc === 'FIELD') {
              if (action === 'DELETE') { p.field = p.field.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
              else if (action === 'TAP') { const fc = p.field.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          } else if (ui.cardActionTarget!.loc === 'RESOURCE') {
               if (action === 'DELETE') { p.resources = p.resources.filter(c => c.instanceId !== ui.cardActionTarget!.instanceId); } 
               else if (action === 'TAP') { const fc = p.resources.find(c => c.instanceId === ui.cardActionTarget!.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          }
          return nextState;
      });
      ui.setCardActionTarget(null);
  };

  const startPlayFromHere = (isCpu: boolean) => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'STREET', phase: Phase.MAIN, isSandboxRun: true, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu } : p) };
      });
      ui.setShowPlaySetup(false); ui.setSandboxToolsOpen(false);
  };

  const returnToSandbox = () => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'SANDBOX', isSandboxRun: false, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu: false } : p) };
      });
      ui.setSandboxToolsOpen(true);
  };

  // Initial Draw Effect (Moved logic slightly to ensure it runs once)
  useEffect(() => {
    if (gameState && gameState.mode !== 'SANDBOX' && gameState.mode !== 'TUTORIAL' && gameState.phase === Phase.INIT_SELECT && !ui.isCoinFlipping) {
      if (!isDrawingInitialRef.current) {
        const p1 = gameState.players[0];
        const p2 = gameState.players[1];
        if (p1.hand.length === 0 || p2.hand.length === 0) {
             isDrawingInitialRef.current = true;
             // Add a small delay to ensure refs/layout are stable
             setTimeout(() => {
                 (async () => {
                     await drawCards(0, 8);
                     await drawCards(1, 8);
                     setGameState(prev => prev ? { ...prev, logs: addLog(prev, "Deployment Phase: Select 3 resources.") } : null);
                     isDrawingInitialRef.current = false;
                 })();
             }, 200);
        }
      }
    }
  }, [gameState?.phase, ui.isCoinFlipping, gameState?.mode]);

  if (!gameState) {
      return (
        <div className="relative flex flex-col items-center justify-center h-screen w-full bg-slate-950 overflow-hidden selection:bg-indigo-500/30">
            <MainMenuBackground />
            <MainMenu 
                menuStep={ui.menuStep}
                setMenuStep={ui.setMenuStep}
                handleModeSelect={handleModeSelect}
                handleStartGameClick={handleStartGameClick}
                handleSpectateClick={handleSpectateClick}
                startLesson={startLesson}
            />
        </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const isHotseat = !gameState.players[1].isCpu || gameState.mode === 'SANDBOX';
  const viewPlayerId = isHotseat ? activeDecisionPlayerId : 0; 
  const bottomPlayer = gameState.players[viewPlayerId];
  const topPlayer = gameState.players[viewPlayerId === 0 ? 1 : 0];
  const isPlayerTurn = activeDecisionPlayerId === viewPlayerId;
  const isActivePlayerCpu = gameState.players[activeDecisionPlayerId].isCpu;
  const isInteractive = isPlayerTurn && !isActivePlayerCpu;
  const tutorialComplete = gameState.tutorialState?.completed;

  const gameHandlers = {
      onCardClick: interactions.handleCardClick,
      onDragStart: interactions.handleDragStart,
      onPhaseAction: interactions.handlePhaseAction,
      setViewingDiscard: ui.setViewingDiscard,
      setShowMenu: ui.setShowMenu,
      toggleLog: () => ui.setShowMobileLog(!ui.showMobileLog)
  };

  return (
    <div 
      className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" 
      ref={refs.containerRef}
      onMouseMove={(e) => {
          if (interactions.dragState) interactions.setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
      }}
      onMouseUp={(e) => interactions.handleDrop(e.nativeEvent)}
      onClick={handleGlobalClick}
    >
      {ui.isCoinFlipping && (
           <CoinFlipOverlay 
                p1Name={gameState.players[0].name} 
                p2Name={gameState.players[1].name} 
                onComplete={(winner) => {
                    setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null);
                    ui.setIsCoinFlipping(false);
                }} 
           />
      )}

      {gameState.tutorialState?.active && !tutorialComplete && gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex] && (
          <TutorialOverlay step={gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex]} onNext={handleTutorialNext} />
      )}

      {tutorialComplete && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
