      {effects.specialAnim && <SpecialCardAnimation type={effects.specialAnim.type as 'K' | 'Q' | 'J'} card={effects.specialAnim.card} targetRect={effects.specialAnim.targetRect} onComplete={() => effects.setSpecialAnim(null)} />}

